import { motion } from "framer-motion";
import { useState } from "react";

export default function Contact() {
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    experience: "",
    specialization: "",
    message: "",
  });

  const [status, setStatus] = useState("");

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus("Submitting...");

    try {
      const res = await fetch("http://localhost:5001/api/trainers/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });

      if (res.ok) {
        setStatus("Application submitted successfully ✅");
        setForm({
          name: "",
          email: "",
          phone: "",
          experience: "",
          specialization: "",
          message: "",
        });
      } else {
        setStatus("Something went wrong ❌");
      }
    } catch {
      setStatus("Server error ❌");
    }
  };

  return (
    <section
      id="contact"
      className="relative bg-black py-32 px-6 overflow-hidden"
    >
      {/* BACKGROUND GLOWS */}
      <div className="absolute -top-40 -left-40 w-[500px] h-[500px] bg-[#e9b21a]/10 blur-[140px]" />
      <div className="absolute -bottom-40 -right-40 w-[500px] h-[500px] bg-[#e9b21a]/10 blur-[140px]" />

      <div className="relative max-w-7xl mx-auto grid lg:grid-cols-2 gap-20 items-center">

        {/* LEFT CONTENT – NO REVEAL SLIDE */}
        <div className="space-y-8">
          <h2 className="text-4xl md:text-5xl font-bold leading-tight">
            Join the <span className="text-[#e9b21a]">Bodyzeal Elite</span>
          </h2>

          <p className="text-gray-400 max-w-lg">
            We don’t just hire trainers. We build leaders, mentors, and fitness
            professionals who redefine transformation.
          </p>

          <div className="grid gap-4 text-sm text-gray-300">
            <div className="flex gap-3">
              <span className="text-[#e9b21a]">✦</span>
              Premium gym environment & loyal clientele
            </div>
            <div className="flex gap-3">
              <span className="text-[#e9b21a]">✦</span>
              Career growth & brand-backed credibility
            </div>
            <div className="flex gap-3">
              <span className="text-[#e9b21a]">✦</span>
              Performance-based earnings & respect
            </div>
          </div>

          <p className="text-xs text-gray-500">
            Applications are reviewed personally by our management team.
          </p>
        </div>

        {/* FORM – ADVANCED STAGGER ANIMATION */}
        <motion.form
          onSubmit={handleSubmit}
          initial="hidden"
          whileInView="show"
          viewport={{ once: true }}
          variants={{
            hidden: { opacity: 0 },
            show: {
              opacity: 1,
              transition: { staggerChildren: 0.08 },
            },
          }}
          className="relative bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-10"
        >
          {/* FORM GLOW BORDER */}
          <div className="absolute inset-0 rounded-3xl ring-1 ring-[#e9b21a]/20 pointer-events-none" />

          {[
            { name: "name", placeholder: "Full Name", type: "text" },
            { name: "email", placeholder: "Email Address", type: "email" },
            { name: "phone", placeholder: "Phone Number", type: "tel" },
            { name: "experience", placeholder: "Years of Experience", type: "text" },
            {
              name: "specialization",
              placeholder: "Specialization (PT / Yoga / Zumba etc.)",
              type: "text",
            },
          ].map((field) => (
            <motion.input
              key={field.name}
              variants={{
                hidden: { opacity: 0, y: 20 },
                show: { opacity: 1, y: 0 },
              }}
              type={field.type}
              name={field.name}
              placeholder={field.placeholder}
              value={form[field.name]}
              onChange={handleChange}
              required
              className="w-full mb-4 bg-black/80 border border-white/15 rounded-xl px-4 py-3 focus:border-[#e9b21a] outline-none"
            />
          ))}

          <motion.textarea
            variants={{
              hidden: { opacity: 0, y: 20 },
              show: { opacity: 1, y: 0 },
            }}
            name="message"
            rows="4"
            placeholder="Tell us about your certifications & mindset"
            value={form.message}
            onChange={handleChange}
            required
            className="w-full mb-6 bg-black/80 border border-white/15 rounded-xl px-4 py-3 focus:border-[#e9b21a] outline-none resize-none"
          />

          <motion.button
            variants={{
              hidden: { opacity: 0, y: 20 },
              show: { opacity: 1, y: 0 },
            }}
            type="submit"
            className="w-full py-3 rounded-full bg-[#e9b21a] text-black font-semibold hover:bg-[#d4a018] transition"
          >
            Apply as Trainer
          </motion.button>

          {status && (
            <p className="mt-4 text-center text-sm text-gray-400">
              {status}
            </p>
          )}
        </motion.form>
      </div>
    </section>
  );
}
